CREATE TYPE "ProductImageOwnership" AS ENUM ('LEGACY_PUBLIC','MANAGED_BLOB','EXTERNAL');
CREATE TYPE "ProductRecommendationState" AS ENUM ('ACTIVE','DISABLED');
CREATE TYPE "ProductRecommendationPriority" AS ENUM ('LOW','NORMAL','HIGH','CRITICAL');
CREATE TYPE "ProductRecommendationTargetType" AS ENUM ('PLANT','DISEASE','PEST','DEFICIENCY');
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY,"legacyId" INTEGER UNIQUE,"category" TEXT NOT NULL,"nameAr" TEXT NOT NULL,"nameEn" TEXT NOT NULL,"shortDescription" TEXT NOT NULL,"description" TEXT NOT NULL,"composition" TEXT NOT NULL,"dosage" TEXT NOT NULL,"packageSize" TEXT NOT NULL,"benefits" JSONB NOT NULL,"crops" JSONB NOT NULL,"createdByUserId" TEXT NOT NULL,"updatedByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ProductAlias" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"value" TEXT NOT NULL,"normalizedValue" TEXT NOT NULL,"locale" TEXT);
CREATE TABLE "ProductImage" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"ownership" "ProductImageOwnership" NOT NULL,"storageKey" TEXT UNIQUE,"url" TEXT NOT NULL,"alt" TEXT NOT NULL,"contentType" TEXT,"fileSize" INTEGER,"width" INTEGER,"height" INTEGER,"checksum" TEXT,"sortOrder" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProductRecommendation" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL,"targetType" "ProductRecommendationTargetType" NOT NULL,"plantId" TEXT,"diseaseId" TEXT,"pestId" TEXT,"deficiencyId" TEXT,"state" "ProductRecommendationState" NOT NULL DEFAULT 'ACTIVE',"priority" "ProductRecommendationPriority" NOT NULL DEFAULT 'NORMAL',"usageContext" TEXT,"compatibility" TEXT,"contraindications" TEXT,"notes" TEXT);
CREATE TABLE "ProductKnowledgeSync" ("productId" TEXT PRIMARY KEY,"status" "KnowledgeSyncStatus" NOT NULL DEFAULT 'PENDING',"lastSyncedAt" TIMESTAMP(3),"diagnosticCode" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "ProductAlias_productId_normalizedValue_key" ON "ProductAlias"("productId","normalizedValue"); CREATE UNIQUE INDEX "ProductImage_productId_sortOrder_key" ON "ProductImage"("productId","sortOrder"); CREATE INDEX "Product_category_idx" ON "Product"("category"); CREATE INDEX "Product_createdByUserId_idx" ON "Product"("createdByUserId"); CREATE INDEX "ProductAlias_normalizedValue_idx" ON "ProductAlias"("normalizedValue"); CREATE INDEX "ProductRecommendation_targetType_idx" ON "ProductRecommendation"("targetType"); CREATE INDEX "ProductRecommendation_plantId_idx" ON "ProductRecommendation"("plantId"); CREATE INDEX "ProductRecommendation_diseaseId_idx" ON "ProductRecommendation"("diseaseId"); CREATE INDEX "ProductRecommendation_pestId_idx" ON "ProductRecommendation"("pestId"); CREATE INDEX "ProductRecommendation_deficiencyId_idx" ON "ProductRecommendation"("deficiencyId"); CREATE INDEX "ProductKnowledgeSync_status_idx" ON "ProductKnowledgeSync"("status");
ALTER TABLE "Product" ADD FOREIGN KEY ("id") REFERENCES "KnowledgeEntity"("id") ON DELETE RESTRICT; ALTER TABLE "Product" ADD FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT; ALTER TABLE "Product" ADD FOREIGN KEY ("updatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT; ALTER TABLE "ProductAlias" ADD FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE; ALTER TABLE "ProductImage" ADD FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE; ALTER TABLE "ProductRecommendation" ADD FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE; ALTER TABLE "ProductRecommendation" ADD FOREIGN KEY ("plantId") REFERENCES "Plant"("id") ON DELETE CASCADE; ALTER TABLE "ProductRecommendation" ADD FOREIGN KEY ("diseaseId") REFERENCES "Disease"("id") ON DELETE CASCADE; ALTER TABLE "ProductRecommendation" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "ProductRecommendation" ADD FOREIGN KEY ("deficiencyId") REFERENCES "Deficiency"("id") ON DELETE CASCADE; ALTER TABLE "ProductKnowledgeSync" ADD FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE;
